<script setup>
import {ref,onMounted,watch,computed} from 'vue';import Pager from './Pager.vue';
const p=defineProps({request:Function,admin:Boolean,publicView:Boolean});const rows=ref([]),page=ref(1),size=ref(10),total=ref(0),error=ref(''),busy=ref(false),selectedType=ref('');
const types={EXPRESS:{name:'快递代拿',icon:'▣',desc:'代取驿站包裹，送到宿舍楼下',color:'orange'},ERRAND:{name:'校园跑腿',icon:'↗',desc:'代买、代送、代办校园小事',color:'blue'},FOOD:{name:'小吃街外卖',icon:'♨',desc:'小吃街美食，及时送到手边',color:'green'}};const names={WAITING:'待接单',ACCEPTED:'已接单',PICKED_UP:'已取件',DELIVERING:'配送中',COMPLETED:'已完成',CANCELLED:'已取消'};
const activeCount=computed(()=>rows.value.filter(x=>['WAITING','ACCEPTED','PICKED_UP','DELIVERING'].includes(x.status)).length);const completedCount=computed(()=>rows.value.filter(x=>x.status==='COMPLETED').length);
async function load(){busy.value=true;error.value='';try{const q=selectedType.value?`&type=${selectedType.value}`:'';const url=p.admin?`/delivery/admin/orders?page=${page.value}&size=${size.value}${q}`:p.publicView?`/delivery/public?page=${page.value}&size=${size.value}`:`/delivery?page=${page.value}&size=${size.value}`;const d=await p.request(url,undefined,'get');rows.value=d.records||[];total.value=d.total||0}catch(e){error.value=e.message}finally{busy.value=false}}async function change(x,status){try{await p.request(`/delivery/${x.id}/status`,{status},'put');load()}catch(e){error.value=e.message}}watch([page,size],load);onMounted(load)
</script>
<template><section class="delivery-page"><div class="delivery-hero"><div><span class="eyebrow">CAMPUS DELIVERY / 校园配送</span><h2>把校园里的每一程<br><em>送到你身边。</em></h2><p>快递代拿、校园跑腿、小吃街外卖，一站式校园生活服务。</p></div><div class="hero-route"><span>取件点</span><b>→</b><span>你的身边</span></div></div><div class="service-grid"><button v-for="(v,k) in types" :key="k" :class="['service-card',v.color,{active:selectedType===k}]" @click="selectedType=selectedType===k?'':k;page=1;load()"><div class="service-art" :class="v.color"><span v-if="k==='EXPRESS'">▣</span><span v-else-if="k==='ERRAND'">⌁</span><span v-else>♨</span><i></i></div><div><small class="service-index">0{{Object.keys(types).indexOf(k)+1}}</small><b>{{v.name}}</b><small>{{v.desc}}</small></div><span>›</span></button></div><div class="delivery-toolbar"><div><h3>{{admin?'配送订单管理':publicView?'公开配送动态':'我的配送订单'}}</h3><p>当前平台配送服务</p></div><div class="stats"><span><b>{{total}}</b>全部订单</span><span><b>{{activeCount}}</b>进行中</span><span><b>{{completedCount}}</b>已完成</span></div></div><div class="filter-row"><button :class="{active:!selectedType}" @click="selectedType='';page=1;load()">全部</button><button v-for="(v,k) in types" :key="k" :class="{active:selectedType===k}" @click="selectedType=k;page=1;load()">{{v.name}}</button></div><p v-if="error" class="error" role="alert">{{error}}</p><div class="delivery-list"><article v-for="x in rows" :key="x.id" class="delivery-card"><div class="card-top"><span :class="['type-pill',types[x.deliveryType]?.color]">{{types[x.deliveryType]?.name||'校园配送'}}</span><b>{{names[x.status]||x.status}}</b></div><h4>{{x.pickupLocation}} <span>→</span> {{x.deliveryLocation}}</h4><p class="order-meta">{{x.deliveryNo}} · 配送费 ¥{{x.fee}} · {{x.createdAt}}</p><div class="progress-line"><i :class="{done:x.status!=='WAITING'}"></i><i :class="{done:['PICKED_UP','DELIVERING','COMPLETED'].includes(x.status)}"></i><i :class="{done:['DELIVERING','COMPLETED'].includes(x.status)}"></i><i :class="{done:x.status==='COMPLETED'}"></i></div><div class="actions"><button v-if="!admin&&!publicView&&x.status==='WAITING'" @click="change(x,'CANCELLED')">取消订单</button><button v-if="!admin&&!publicView&&x.status==='WAITING'" class="primary" @click="change(x,'ACCEPTED')">接单</button><button v-if="!admin&&!publicView&&x.status==='ACCEPTED'" class="primary" @click="change(x,'PICKED_UP')">确认取件</button><button v-if="!admin&&!publicView&&x.status==='PICKED_UP'" class="primary" @click="change(x,'DELIVERING')">开始配送</button><button v-if="!admin&&!publicView&&x.status==='DELIVERING'" class="primary" @click="change(x,'COMPLETED')">完成配送</button></div></article></div><div v-if="!rows.length&&!busy" class="empty"><div>⌁</div><h3>还没有配送订单</h3><p>选择上方服务类型，开始你的校园配送体验</p></div><Pager v-model:page="page" v-model:size="size" :total="total" :busy="busy"/></section></template>
